    """Process liveness only; does not touch PostgreSQL."""
    return LiveResponse(status="ok")


@router.get(
    "/ready",
    response_model=ReadyResponse,
    responses={503: {"model": ReadyResponse}},
)
def ready(request: Request) -> JSONResponse:
    """Ping PostgreSQL; worker/checkpointer liveness is not observed by this process."""
    try:
        ping_database(request.app.state.engine)
        database = CheckResult(status="ok")
    except (SQLAlchemyError, OSError):
        # Do not include the exception text; SQLAlchemy messages can contain the URL.
        database = CheckResult(status="error", detail="database_unreachable")

    payload = ReadyResponse(
        status="ready" if database.status == "ok" else "degraded",
        checks=ReadyChecks(
            database=database,
            checkpointer=CheckResult(status="not_observed", detail="not_observed_by_api"),
            worker=CheckResult(status="not_observed", detail="not_observed_by_api"),
        ),
    )
    return JSONResponse(
        content=payload.model_dump(exclude_none=True),
        status_code=200 if payload.status == "ready" else 503,
    )
"""FastAPI application factory, CORS, and route mounting."""

from collections.abc import AsyncIterator
from contextlib import asynccontextmanager

from fastapi import FastAPI
from fastapi.middleware.cors import CORSMiddleware

from agentforge.api.routes_health import router as health_router
from agentforge.api.routes_tasks import router as tasks_router
from agentforge.api.routes_events import router as events_router
from agentforge.api.routes_projects import router as projects_router
from agentforge.api.routes_artifacts import router as artifacts_router
from agentforge.api.routes_configuration import router as configuration_router
from agentforge.auth.routes import router as auth_router
from agentforge.auth.session import SessionStore
from agentforge.database.engine import create_db_engine
from agentforge.settings import Settings, get_settings


@asynccontextmanager
async def lifespan(app: FastAPI) -> AsyncIterator[None]:
    settings: Settings = app.state.settings
    owns_engine = not hasattr(app.state, "engine")
    if owns_engine:
        app.state.engine = create_db_engine(settings.database_url)
    try:
        yield
    finally:
        if owns_engine:
            app.state.engine.dispose()


def create_app(settings: Settings | None = None) -> FastAPI:
    """Build the ASGI app. Uvicorn loads `agentforge.main:app`."""
    resolved = settings or get_settings()
    app = FastAPI(
        title="AgentForge AI API",
        version="0.1.0",
        description="HTTP API for the AgentForge AI workspace.",
        lifespan=lifespan,
        openapi_tags=[
            {
                "name": "health",
                "description": "Liveness and readiness probes.",
            }
        ],
    )
    app.state.settings = resolved
    app.state.auth_sessions = SessionStore()
    app.add_middleware(
        CORSMiddleware,
        allow_origins=resolved.allowed_origins,
        allow_credentials=True,
        allow_methods=["GET", "POST", "PUT", "PATCH", "DELETE", "OPTIONS"],
        allow_headers=["*"],
    )
    app.include_router(health_router)
    app.include_router(auth_router)
    app.include_router(projects_router)
    app.include_router(tasks_router)
    app.include_router(events_router)
    app.include_router(artifacts_router)
    app.include_router(configuration_router)
    @app.middleware("http")
    async def private_response_headers(request, call_next):
        response = await call_next(request)
        if request.url.path.startswith("/api/v1/") and not request.url.path.startswith("/api/v1/health/"):
            response.headers["Cache-Control"] = "no-store"
            response.headers["X-Content-Type-Options"] = "nosniff"
        return response
    return app


app = create_app()
"""Authenticated task submission and durable task state."""

from uuid import UUID

from fastapi import APIRouter, Depends, HTTPException, Query, Request

from agentforge.api.dependencies import task_repository
from agentforge.auth.session import current_user
from agentforge.contracts.tasks import TaskCreate, TaskStepView, TaskView
from agentforge.database.models import User
from agentforge.repositories.tasks import TaskConflict, TaskNotFound, TaskRepository

router = APIRouter(prefix="/api/v1/tasks", tags=["tasks"])


@router.post("", response_model=TaskView, status_code=202)
def create_task(body: TaskCreate, request: Request, user: User = Depends(current_user),
                repository: TaskRepository = Depends(task_repository)) -> TaskView:
    try:
        return repository.create(owner_id=user.id, request=body)
    except TaskNotFound:
        raise HTTPException(404, "project_not_found") from None
    except TaskConflict as error:
        raise HTTPException(409, str(error)) from None


@router.get("", response_model=list[TaskView])
def list_tasks(user: User = Depends(current_user),
               repository: TaskRepository = Depends(task_repository),
               project_id: UUID | None = None, limit: int = Query(50, ge=1, le=100),
               offset: int = Query(0, ge=0, le=10000)) -> list[TaskView]:
    return repository.list(owner_id=user.id, project_id=project_id, limit=limit, offset=offset)


@router.get("/{task_id}", response_model=TaskView)
def get_task(task_id: UUID, user: User = Depends(current_user),
             repository: TaskRepository = Depends(task_repository)) -> TaskView:
    try:
        return repository.get(task_id=task_id, owner_id=user.id)
    except TaskNotFound:
        raise HTTPException(404, "task_not_found") from None


@router.get("/{task_id}/steps", response_model=list[TaskStepView])
def get_steps(task_id: UUID, user: User = Depends(current_user),
              repository: TaskRepository = Depends(task_repository)) -> list[TaskStepView]:
    try:
        return repository.steps(task_id=task_id, owner_id=user.id)
    except TaskNotFound:
        raise HTTPException(404, "task_not_found") from None


@router.get("/{task_id}/runs")
def get_runs(task_id: UUID, user: User = Depends(current_user),
             repository: TaskRepository = Depends(task_repository)) -> list[dict]:
    try:
        return repository.runs(task_id=task_id, owner_id=user.id)
    except TaskNotFound:
        raise HTTPException(404, "task_not_found") from None


@router.post("/{task_id}/cancel", response_model=TaskView, status_code=202)
def cancel_task(task_id: UUID, user: User = Depends(current_user),
                repository: TaskRepository = Depends(task_repository)) -> TaskView:
    try:
        return repository.cancel(task_id=task_id, owner_id=user.id)
    except TaskNotFound:
        raise HTTPException(404, "task_not_found") from None
    except TaskConflict as error:
        raise HTTPException(409, str(error)) from None


@router.post("/{task_id}/resume")
def resume_task(task_id: UUID, user: User = Depends(current_user),
                repository: TaskRepository = Depends(task_repository)) -> None:
    # Crash recovery is lease/checkpoint driven. Replaying an uncertain paid effect
    # from a browser request would bypass the durable reconciliation policy.
    try:
        repository.get(task_id=task_id, owner_id=user.id)
    except TaskNotFound:
        raise HTTPException(404, "task_not_found") from None
    raise HTTPException(409, "manual_resume_not_available; worker_recovers_eligible_checkpoints")

